	@ParameterizedTest(name = "structuralBoundary={0}")
	@ValueSource(strings = { "variable", "independent" })
	void actualStructuralScopeBoundariesDoNotBorrowOuterBindings(String boundary, @TempDir Path directory) {
		var organizations = assignment(List.of("org"), List.of(
				new ListBindingSet(List.of("org"), end(0)), new ListBindingSet(List.of("org"), end(1))));
		StatementPattern member = pattern("person", MEMBER, "org");
		if (boundary.equals("variable")) {
			member.setVariableScopeChange(true);
		} else {
			member.setIndependentInputScope(true);
		}
		try (NativeFixture fixture = new NativeFixture(directory)) {
			fixture.withSession(new Join(organizations, member), nativeSession -> {
				var call = nativeSession.call;
				PackedCostEstimate prefix = nativeSession.pricePrefix(call.leftRelationId());
				PackedCostEstimate output = nativeSession.leaf(call.rightRelationId());
				double isolatedRows = output.outputRows();
				double isolatedWork = output.workRows();
				int isolatedKey = output.lookupComponentMask();
				var context = PackedObservedFrameTestSupport.withCapturedSemanticScope(
						PackedCostTestSupport.restrictedPrefixContext(new int[] { call.leftRelationId() }, 1,
								prefix.outputRows(), prefix.evidenceStateId()),
						call, call.rightRelationId());
				assertNotEquals(PackedObservedFrameTestSupport.structuralScopeFlags(call.emptyContext()),
						PackedObservedFrameTestSupport.structuralScopeFlags(context),
						"the real source annotation must establish a structural boundary");
				nativeSession.session.appendFactor(call.rightRelationId(), context, output);
				assertEquals(isolatedRows, output.outputRows(), 0.0d);
				assertEquals(isolatedWork, output.workRows(), 0.0d);
				assertEquals(isolatedKey, output.lookupComponentMask());
				assertFalse(output.hasContextualOutputRows());
				assertEquals(0, output.evidenceStateId());
				return null;
			});
		}
	}

